from aliyunsdkcore.request import RpcRequest
from aliyunsdkvpc.endpoint import endpoint_data

class UpdateRouteTargetGroupRequest(RpcRequest):

	def __init__(self):
		RpcRequest.__init__(self, 'Vpc', '2016-04-28', 'UpdateRouteTargetGroup','vpc')
		self.set_protocol_type('https')
		self.set_method('POST')

		if hasattr(self, "endpoint_map"):
			setattr(self, "endpoint_map", endpoint_data.getEndpointMap())
		if hasattr(self, "endpoint_regional"):
			setattr(self, "endpoint_regional", endpoint_data.getEndpointRegional())

	def get_ClientToken(self): # String
		return self.get_query_params().get('ClientToken')

	def set_ClientToken(self, ClientToken):  # String
		self.add_query_param('ClientToken', ClientToken)
	def get_RouteTargetGroupId(self): # String
		return self.get_query_params().get('RouteTargetGroupId')

	def set_RouteTargetGroupId(self, RouteTargetGroupId):  # String
		self.add_query_param('RouteTargetGroupId', RouteTargetGroupId)
	def get_RouteTargetMemberLists(self): # RepeatList
		return self.get_query_params().get('RouteTargetMemberList')

	def set_RouteTargetMemberLists(self, RouteTargetMemberList):  # RepeatList
		for depth1 in range(len(RouteTargetMemberList)):
			if RouteTargetMemberList[depth1].get('MemberId') is not None:
				self.add_query_param('RouteTargetMemberList.' + str(depth1 + 1) + '.MemberId', RouteTargetMemberList[depth1].get('MemberId'))
			if RouteTargetMemberList[depth1].get('MemberType') is not None:
				self.add_query_param('RouteTargetMemberList.' + str(depth1 + 1) + '.MemberType', RouteTargetMemberList[depth1].get('MemberType'))
			if RouteTargetMemberList[depth1].get('Weight') is not None:
				self.add_query_param('RouteTargetMemberList.' + str(depth1 + 1) + '.Weight', RouteTargetMemberList[depth1].get('Weight'))
	def get_RouteTargetGroupName(self): # String
		return self.get_query_params().get('RouteTargetGroupName')

	def set_RouteTargetGroupName(self, RouteTargetGroupName):  # String
		self.add_query_param('RouteTargetGroupName', RouteTargetGroupName)
	def get_RouteTargetGroupDescription(self): # String
		return self.get_query_params().get('RouteTargetGroupDescription')

	def set_RouteTargetGroupDescription(self, RouteTargetGroupDescription):  # String
		self.add_query_param('RouteTargetGroupDescription', RouteTargetGroupDescription)
